//! AstroPort bridge: the only component that knows both engines (docs/rewrite/design.md).
//! Constructor, start sequence (3.4) and shutdown callback (3.8).

// The unsafe functions here are entries of the C tables; their contracts are in design.md 3.
#![allow(clippy::missing_safety_doc)]

/// Generated by build.rs from Kyty's LIB_FUNC lines: `SLOTS`, `EXPORT_COUNT`, `MEMORY_COUNT`,
/// `HASH8`, and the macro `astroport_entry_symbol!()` for `#[export_name = ...]`.
#[macro_use]
pub mod nids {
    include!(concat!(env!("OUT_DIR"), "/nids.rs"));
}

pub mod abi;
pub mod audio;
pub mod config;
pub mod entry;
pub mod events;
pub mod fault;
pub mod limiter;
pub mod live;
pub mod memory;
pub mod pad;

use abi::{AstroportHostApi, ExternalRenderer, KytyEmbedApi, KytyEmbedHooks, PadData, ASTROPORT_HOST_ABI, KYTY_EMBED_ABI};
use std::ffi::{c_void, CStr, CString};
use std::sync::atomic::{AtomicBool, AtomicPtr, Ordering};
use std::sync::{mpsc, Condvar, Mutex, OnceLock};
use std::time::{Duration, Instant};

static KYTY: AtomicPtr<KytyEmbedApi> = AtomicPtr::new(std::ptr::null_mut());
static HOST: AtomicPtr<AstroportHostApi> = AtomicPtr::new(std::ptr::null_mut());
/// Shutdown started: relay and pump leave their loops, pad audio is refused.
pub static STOP: AtomicBool = AtomicBool::new(false);
static STARTED: OnceLock<Instant> = OnceLock::new();
static RESERVED: (Mutex<bool>, Condvar) = (Mutex::new(false), Condvar::new());

pub fn die(message: impl std::fmt::Display) -> ! {
    eprintln!("astroport: {message}");
    std::process::abort()
}

/// Milliseconds since the bridge started; 0 in a process without engines.
pub fn uptime_ms() -> u128 {
    STARTED.get().map_or(0, |start| start.elapsed().as_millis())
}

/// Kyty's table. Valid after `set_engines`.
pub fn kyty() -> &'static KytyEmbedApi {
    let table = KYTY.load(Ordering::Acquire);
    assert!(!table.is_null());
    unsafe { &*table }
}

/// The host's table. Valid after `set_engines`.
pub fn host() -> &'static AstroportHostApi {
    let table = HOST.load(Ordering::Acquire);
    assert!(!table.is_null());
    unsafe { &*table }
}

/// False in a process whose constructor found no engines (and in tools and tests that set none).
pub fn started() -> bool {
    !KYTY.load(Ordering::Acquire).is_null()
}

/// # Safety
/// Both tables must live for the process.
pub unsafe fn set_engines(kyty: *const KytyEmbedApi, host: *const AstroportHostApi) {
    KYTY.store(kyty.cast_mut(), Ordering::Release);
    HOST.store(host.cast_mut(), Ordering::Release);
}

macro_rules! require {
    ($table:ident: $($entry:ident)*) => {
        $(if $table.$entry.is_none() {
            return Err(concat!(stringify!($entry), " is null").into());
        })*
    };
}

const FNS: [&str; 14] = [
    "pad_init",
    "pad_open",
    "pad_get_handle",
    "pad_read_state",
    "pad_set_vibration",
    "pad_set_light_bar",
    "pad_reset_light_bar",
    "pad_set_trigger_effect",
    "equeue_create",
    "equeue_wait",
    "equeue_add_user_event",
    "equeue_trigger_user_event",
    "agc_add_eq_event",
    "video_out_add_flip_event",
];

/// Exact abi, size at least ours, no null among the entries the bridge needs (design.md 3.2).
///
/// # Safety
/// `kyty` must point at a table that starts with abi and size and is `size` bytes long.
pub unsafe fn check_kyty(kyty: *const KytyEmbedApi) -> Result<(), String> {
    let (abi, size) = ((*kyty).abi, (*kyty).size as usize);
    if abi != KYTY_EMBED_ABI || size < size_of::<KytyEmbedApi>() {
        return Err(format!("abi {abi} size {size}, need abi {KYTY_EMBED_ABI} size >= {}", size_of::<KytyEmbedApi>()));
    }
    let kyty = &*kyty;
    if kyty.pad_data_size as usize != size_of::<PadData>() {
        return Err(format!("pad_data_size {}, need {}", kyty.pad_data_size, size_of::<PadData>()));
    }
    require!(kyty: run find fault flush user_id pad_audio set_low_latency_interval set_window_size);
    if kyty.fns.is_null() {
        return Err("fns is null".into());
    }
    let fns = &*(kyty.fns as *const [*const c_void; 14]);
    match fns.iter().position(|address| address.is_null()) {
        Some(missing) => Err(format!("fns.{} is null", FNS[missing])),
        None => Ok(()),
    }
}

/// # Safety
/// As `check_kyty`.
pub unsafe fn check_host(host: *const AstroportHostApi) -> Result<(), String> {
    let (abi, size) = ((*host).abi, (*host).size as usize);
    if abi != ASTROPORT_HOST_ABI || size < size_of::<AstroportHostApi>() {
        return Err(format!("abi {abi} size {size}, need abi {ASTROPORT_HOST_ABI} size >= {}", size_of::<AstroportHostApi>()));
    }
    let host = &*host;
    require!(host: donate event_add event_delete event_deliver pad_publish pad_fetch_output request_exit on_shutdown install_renderer);
    Ok(())
}

/// What AnyPS5's libkernel forwards to (design.md 2.2).
pub static EXTERNAL_RENDERER: ExternalRenderer = ExternalRenderer {
    size: size_of::<ExternalRenderer>() as u32,
    memory: entry::MEMORY_THUNKS,
    owns: memory::owns_c,
    pad_audio: audio::pad_audio,
    haptic_gain: audio::haptic_gain,
    video_active: audio::video_active,
};

pub static HOOKS: KytyEmbedHooks = KytyEmbedHooks {
    size: size_of::<KytyEmbedHooks>() as u32,
    reserved: Some(reserved),
    ready: Some(ready),
    present_gate: Some(limiter::present_gate),
    presented: Some(limiter::presented),
    live_setting: Some(live::live_setting),
};

/// Not a game process (cargo test, a tool) when neither engine is loaded.
unsafe extern "C" fn constructor() {
    let lookup = |name: &CStr| libc::dlsym(libc::RTLD_DEFAULT, name.as_ptr());
    let (kyty, host) = (lookup(c"kyty_embed_api"), lookup(c"AstroportHostApi_nid_no_patch"));
    match (kyty.is_null(), host.is_null()) {
        (true, true) => return,
        (true, false) => die("kyty_embed_api not found: libkyty_renderer.so is not loaded"),
        (false, true) => die("AstroportHostApi_nid_no_patch not found: libAstroportHost.prx is not loaded"),
        (false, false) => {}
    }
    let kyty: unsafe extern "C" fn() -> *const KytyEmbedApi = std::mem::transmute(kyty);
    let host: unsafe extern "C" fn() -> *const AstroportHostApi = std::mem::transmute(host);
    start(kyty(), host());
}

#[used]
#[link_section = ".init_array"]
static CONSTRUCTOR: unsafe extern "C" fn() = constructor;

/// Folder of the library (or program) this code is in.
fn library_dir() -> String {
    unsafe {
        let mut info: libc::Dl_info = std::mem::zeroed();
        if libc::dladdr(library_dir as *const c_void, &mut info) == 0 || info.dli_fname.is_null() {
            return ".".into();
        }
        let path = std::path::Path::new(CStr::from_ptr(info.dli_fname).to_str().unwrap_or("."));
        path.parent().map_or(".".into(), |dir| dir.to_string_lossy().into_owned())
    }
}

/// Phase 1 of design.md 3.4. Returns when Kyty holds the guest address space; the renderer
/// keeps starting on its own thread. Any failure prints one line and aborts.
///
/// # Safety
/// Both tables must live for the process; call once, before any guest code runs.
pub unsafe fn start(kyty: *const KytyEmbedApi, host: *const AstroportHostApi) {
    STARTED.set(Instant::now()).unwrap_or_else(|_| die("started twice"));
    check_kyty(kyty).unwrap_or_else(|error| die(format!("KytyEmbedApi: {error}")));
    check_host(host).unwrap_or_else(|error| die(format!("AstroportHostApi: {error}")));
    set_engines(kyty, host);
    let host = crate::host();

    let working_dir = std::env::current_dir().map_or(".".into(), |dir| dir.to_string_lossy().into_owned());
    let config = config::Config::from_env(|name| std::env::var(name).ok(), &working_dir, &library_dir()).unwrap_or_else(|e| die(e));
    limiter::set_limit(config.fps_limit);
    audio::set_haptic_gain(config.haptic_gain);
    live::FULLSCREEN.store(config.fullscreen, Ordering::Relaxed);
    if config.dlss {
        if let Err(error) = std::fs::create_dir_all(&config.ngx_data_dir) {
            eprintln!("astroport: {}: {error}", config.ngx_data_dir);
        }
    }

    memory::donate(host).unwrap_or_else(|e| die(e));
    eprintln!("astroport: donated {:#x?}", memory::DONATED);
    fault::install();
    (host.install_renderer.unwrap())(&EXTERNAL_RENDERER);
    (host.on_shutdown.unwrap())(shutdown);

    let embed = Box::leak(Box::new(config.embed())) as *const _ as usize;
    // Kyty's main thread: the size of a process main stack.
    let renderer = std::thread::Builder::new().name("astroport renderer".into()).stack_size(8 << 20);
    renderer
        .spawn(move || {
            let code = (crate::kyty().run.unwrap())(embed as *const _, &HOOKS);
            if code != 0 {
                die(format!("the renderer stopped with code {code}"));
            }
            // The window was closed: the host exits its usual way, the renderer stays alive.
            (crate::host().request_exit.unwrap())(0);
            loop {
                std::thread::park();
            }
        })
        .unwrap_or_else(|error| die(format!("renderer thread: {error}")));

    let (reserved, changed) = &RESERVED;
    let (_guard, wait) = changed.wait_timeout_while(reserved.lock().unwrap(), Duration::from_secs(10), |done| !*done).unwrap();
    if wait.timed_out() {
        die("the renderer did not reserve the guest address space within 10 s");
    }
    memory::verify_adopted().unwrap_or_else(|e| die(e));
    eprintln!("astroport: adopted {0}/{0}", memory::OWNED.len());
}

unsafe extern "C" fn reserved() {
    *RESERVED.0.lock().unwrap() = true;
    RESERVED.1.notify_all();
}

/// Phase 2, on the renderer thread inside `run`: all Kyty subsystems are up.
unsafe extern "C" fn ready() {
    events::start();
    let own = [
        ("::AgcDriverAddEqEvent", events::agc_add_eq_event as *mut c_void),
        ("::AgcDriverDeleteEqEvent", events::agc_delete_eq_event as *mut c_void),
        ("::VideoOutAddFlipEvent", events::video_out_add_flip_event as *mut c_void),
    ];
    let mut bound_own = 0;
    let mut targets = [std::ptr::null_mut(); entry::SLOT_COUNT];
    for (index, export) in nids::SLOTS.iter().enumerate() {
        let target = match own.iter().find(|(function, _)| export.function.ends_with(function)) {
            Some((_, target)) => {
                bound_own += 1;
                *target
            }
            None => (kyty().find.unwrap())(CString::new(export.nid).unwrap().as_ptr()),
        };
        if target.is_null() {
            die(format!("Kyty does not provide {} ({} {})", export.nid, export.library, export.function));
        }
        targets[index] = target;
    }
    if bound_own != own.len() {
        die("the export table lacks one of the three event functions");
    }
    pad::start();
    // Bound only now, right before READY: the fault handler passes every fault on until READY,
    // so no guest thread may reach Kyty earlier.
    for (index, target) in targets.into_iter().enumerate() {
        entry::bind(index, target);
    }
    entry::publish_ready();
    eprintln!("astroport: renderer ready in {} ms", uptime_ms());
}

/// Registered with the host's shutdown list: stop our threads and flush Kyty, once.
unsafe extern "C" fn shutdown() {
    if STOP.swap(true, Ordering::AcqRel) {
        return;
    }
    if entry::is_ready() {
        events::stop();
        let (done, flushed) = mpsc::channel();
        std::thread::spawn(move || {
            (kyty().flush.unwrap())();
            let _ = done.send(());
        });
        if flushed.recv_timeout(Duration::from_secs(3)).is_err() {
            eprintln!("astroport: the renderer did not flush within 3 s");
        }
    }
    let (handled, passed_on) = fault::counts();
    eprintln!("astroport: exit: write faults handled {handled}, passed on {passed_on}");
}
